      if (event.status !== "completed" || !["edit", "write", "patch", "shell"].includes(event.tool))
        return;
      const ids = advisoriesFor(event.tool, event.input, await directory(event.sessionID)).filter((id) => !shown.has(`${event.sessionID}:${id}`));
      if (ids.length === 0)
        return;
      for (const id of ids)
        shown.add(`${event.sessionID}:${id}`);
